  "turningPoints": [
   {
    "date": "1939-09-03",
    "name": "War begins - Athenia sunk",
    "blurb": "Hours after Britain declares war, U-30 (Lemp) torpedoes the passenger liner SS Athenia northwest of Ireland between Rockall and Tory Island, signalling that a tonnage war on Atlantic shipping has begun.",
    "lat": 56.7,
    "lon": -14
   },
   {
    "date": "1939-10-14",
    "name": "Royal Oak sunk at Scapa Flow",
    "blurb": "Gunther Prien's U-47 slips into the Home Fleet's anchorage and sinks the battleship HMS Royal Oak (833 dead), a propaganda coup that proves the U-boat arm's daring.",
    "lat": 58.92,
    "lon": -2.99
   },
   {
    "date": "1940-06-22",
    "name": "Fall of France - Biscay bases",
    "blurb": "France's armistice (22 Jun) hands the Kriegsmarine Atlantic-facing bases at Lorient, Brest, St Nazaire, La Pallice and Bordeaux, slashing transit times and opening the 'First Happy Time'.",
    "lat": 47.75,
    "lon": -3.37
   },
   {
    "date": "1940-10-18",
    "name": "Convoys SC-7 & HX-79 massacred",
    "blurb": "Donitz's first concentrated 'wolfpack' (Rudeltaktik) tears into SC-7 (17-19 Oct) and HX-79 (19-20 Oct), sinking 32 ships in days for no U-boat losses - the high-water mark of the First Happy Time.",
    "lat": 57,
    "lon": -15
   },
   {
    "date": "1941-05-09",
    "name": "U-110 captured - Enigma seized",
    "blurb": "HMS Bulldog's boarding party recovers an intact Enigma machine and codebooks from U-110 (south of Iceland), a windfall that lets Bletchley Park read U-boat signals and reroute convoys.",
    "lat": 60.5,
    "lon": -33
   },
   {
    "date": "1942-01-13",
    "name": "Operation Drumbeat off the US coast",
    "blurb": "With America newly in the war, the 'Second Happy Time' opens (first sinkings 13-14 Jan): U-boats sink lit, unescorted ships within sight of the US shore until coastal convoys and blackouts are finally imposed.",
    "lat": 35.5,
    "lon": -74.5
   },
   {
    "date": "1942-11-01",
    "name": "Worst month for U-boat sinkings",
    "blurb": "November 1942 sets the war's record for tonnage sunk by U-boats - 768,732 GRT (123 ships) - as the wolfpacks dominate the mid-ocean 'air gap' south of Greenland.",
    "lat": 52,
    "lon": -35
   },
   {
    "date": "1943-03-16",
    "name": "SC-122 / HX-229 - greatest convoy battle",
    "blurb": "Three wolfpacks (38 boats) fall on the merged convoys SC-122 and HX-229 (16-19 Mar), sinking 22 ships for the loss of one U-boat - the largest convoy battle of the war and the climax of the crisis.",
    "lat": 54,
    "lon": -35
   },
   {
    "date": "1943-05-05",
    "name": "Convoy ONS-5 turns the tide",
    "blurb": "ONS-5's escorts, aided by radar and aircraft, sink six U-boats while losing 13 ships - an exchange rate Donitz could not afford and the first time a wolfpack is decisively beaten by its escorts.",
    "lat": 56.5,
    "lon": -42.5
   },
   {
    "date": "1943-05-24",
    "name": "Black May - Donitz withdraws",
    "blurb": "After losing 41 U-boats in May to VLR aircraft, escort carriers, radar and Ultra, Donitz pulls his boats from the North Atlantic, conceding 'We had lost the Battle of the Atlantic'.",
    "lat": 55,
    "lon": -38
   },
   {
    "date": "1944-06-06",
    "name": "D-Day denies the Channel",
    "blurb": "Overwhelming Allied air and sea ASW (Operation Cork) around the Normandy landings seals the Western Approaches and English Channel to U-boats, destroying many that try to intervene.",
    "lat": 49.5,
    "lon": -4
   },
   {
    "date": "1945-05-08",
    "name": "VE-Day - U-boats surrender",
    "blurb": "Donitz orders all boats to cease fire and surface; over 150 surrender while many crews scuttle their boats. The longest continuous campaign of the war ends.",
    "lat": 56,
    "lon": -10
   }
  ],
